const args = $input.first().json;
if (!args.pregunta_usuario || String(args.pregunta_usuario).trim() === '') {
  return [{ json: { status: 'ERROR', message_to_agent: 'Faltó pregunta_usuario.', _skip: true } }];
}
return [{ json: args }];

const faqs = $input.all().map(i => i.json);
const args = $('Execute Workflow Trigger').first().json;
const query = String(args.pregunta_usuario).toLowerCase();
const categoria = (args.categoria_hint || '').toLowerCase();

// Score cada FAQ por keywords matched
function score(faq) {
  const keywords = String(faq.Keywords || '').toLowerCase().split(/[,;]+/).map(k => k.trim()).filter(Boolean);
  let s = 0;
  for (const kw of keywords) {
    if (query.includes(kw)) s += 2;
  }
  // Boost por match de categoría
  if (categoria && String(faq['Categoría'] || '').toLowerCase().includes(categoria)) s += 3;
  // Boost si la pregunta literal aparece en la pregunta del FAQ
  if (faq['Pregunta'] && query.includes(String(faq['Pregunta']).toLowerCase().substring(0, 15))) s += 2;
  return s;
}

const scored = faqs.map(f => ({ faq: f, s: score(f) })).filter(x => x.s >= 1).sort((a, b) => b.s - a.s);

if (scored.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    data: null,
    message_to_agent: 'No encontré una FAQ que matchee esa pregunta. Si es algo común, agregala a Airtable.',
    trace_id: $execution.id
  } }];
}

const best = scored[0].faq;
return [{ json: {
  status: 'RESOLVED',
  data: {
    respuesta_corta: best['Respuesta corta'] || '',
    categoria: best['Categoría'] || '',
    pregunta_matched: best['Pregunta'] || ''
  },
  message_to_agent: `Respuesta encontrada en categoría "${best['Categoría']}". Integrala natural a tu respuesta.`,
  trace_id: $execution.id
} }];
